import httpx

class WeatherService:
    """Fetches real-time environmental metrics for Lucknow Division."""
    BASE_URL = "https://api.open-meteo.com/v1/forecast"

    async def get_live_metrics(self, lat: float, lon: float):
        params = {
            "latitude": lat,
            "longitude": lon,
            "hourly": "precipitation,soil_moisture_0_to_7cm,river_discharge",
            "forecast_days": 1,
            "timezone": "auto"
        }
        async with httpx.AsyncClient() as client:
            try:
                response = await client.get(self.BASE_URL, params=params)
                if response.status_code == 200:
                    data = response.json()
                    # Return the current hour's data point
                    return {
                        "rainfall_mm": data['hourly']['precipitation'][0],
                        "soil_moisture": data['hourly']['soil_moisture_0_to_7cm'][0],
                        "river_discharge": data['hourly'].get('river_discharge', [0])[0]
                    }
            except Exception as e:
                print(f"📡 Weather API Error: {e}")
            return None

